import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.rtg.rtg.genericrtg import GenericRtg

__author__ = "Marcin Usielski"
__copyright__ = "Copyright (C) 2023-2024, Nokia"
__email__ = "marcin.usielski@nokia.com"


class StatsCleanlogdir(GenericRtg):
    """Stats Cleanlogdir command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Stats command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(StatsCleanlogdir, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.add_failure_indication(r"Error getting 'clean' stats:")

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "stats cleanlogdir"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_completed(line)
                self._parse_removed(line)
                self._seconds_ago(line)
            except ParsingDone:
                pass
        return super(StatsCleanlogdir, self).on_new_line(line, is_full_line)

    # Clean-up completed 64.73 MB freed
    _re_completed = re.compile(r"Clean-up completed\s+(?P<VAL>\S+)\s+(?P<UNIT>\w+)\s+freed")

    def _parse_completed(self, line):
        if self._regex_helper.search(self._re_completed, line):
            if "freed" not in self.current_ret:
                self.current_ret["freed"] = {}
            self.current_ret["freed"]["val_raw"] = self._regex_helper.group("VAL")
            self.current_ret["freed"]["val"] = float(self._regex_helper.group("VAL"))
            self.current_ret["freed"]["unit"] = self._regex_helper.group("UNIT")
            raise ParsingDone()

    # '/home/cus/logs/trace.log.0' removed (2.74 KB freed)
    _re_removed = re.compile(r"'(?P<PATH>.*)' removed \((?P<VAL>\S+)\s+(?P<UNIT>\w+)\s+freed\)")

    def _parse_removed(self, line):
        if self._regex_helper.search(self._re_removed, line):
            if "removed" not in self.current_ret:
                self.current_ret["removed"] = {}
            path = self._regex_helper.group("PATH")
            self.current_ret["removed"][path] = {}
            self.current_ret["removed"][path]["val_raw"] = self._regex_helper.group("VAL")
            self.current_ret["removed"][path]["val"] = float(self._regex_helper.group("VAL"))
            self.current_ret["removed"][path]["unit"] = self._regex_helper.group("UNIT")
            raise ParsingDone()

    # Disk clean-up performed 23 s ago. At least 300s break is required
    _re_ago = re.compile(
        r"clean-up performed (?P<AGO>\d+)\s+(?P<AGO_UNIT>\S+) ago. At least (?P<AT_LEAST>\d+)\s*(?P<AT_LEAST_UNIT>\D+)\s+break is required"
    )

    def _seconds_ago(self, line):
        if self._regex_helper.search(self._re_ago, line):
            self.current_ret["ago"] = int(self._regex_helper.group("AGO"))
            self.current_ret["ago_unit"] = self._regex_helper.group("AGO_UNIT")
            self.current_ret["at_least"] = int(self._regex_helper.group("AT_LEAST"))
            self.current_ret["at_least_unit"] = self._regex_helper.group("AT_LEAST_UNIT")
            raise ParsingDone()


